import{_ as s,o as a,c as i,a2 as n}from"./chunks/framework.Ddyno5UB.js";const u=JSON.parse('{"title":"Architecture and Differences","description":"","frontmatter":{},"headers":[],"relativePath":"openshift/1-architecture-and-differences.md","filePath":"openshift/1-architecture-and-differences.md"}'),t={name:"openshift/1-architecture-and-differences.md"};function o(r,e,l,c,h,p){return a(),i("div",null,[...e[0]||(e[0]=[n(`<h1 id="architecture-and-differences" tabindex="-1">Architecture and Differences <a class="header-anchor" href="#architecture-and-differences" aria-label="Permalink to &quot;Architecture and Differences&quot;">​</a></h1><p>Red Hat OpenShift is an enterprise-ready container platform built on top of Kubernetes. While Kubernetes provides the core orchestration engine, OpenShift adds opinionated developer tools, strict security defaults, and integrated CI/CD pipelines.</p><h2 id="what-is-openshift" tabindex="-1">What is OpenShift? <a class="header-anchor" href="#what-is-openshift" aria-label="Permalink to &quot;What is OpenShift?&quot;">​</a></h2><p>OpenShift comes in two primary flavors:</p><ul><li><strong>OCP (OpenShift Container Platform):</strong> The commercial, supported product from Red Hat.</li><li><strong>OKD (Origin Community Distribution):</strong> The upstream, open-source community version of OpenShift (formerly called OpenShift Origin).</li></ul><h3 id="core-differences-from-vanilla-kubernetes" tabindex="-1">Core Differences from Vanilla Kubernetes <a class="header-anchor" href="#core-differences-from-vanilla-kubernetes" aria-label="Permalink to &quot;Core Differences from Vanilla Kubernetes&quot;">​</a></h3><p>If you already know Kubernetes, here are the major differences you will encounter in OpenShift:</p><ol><li><strong>Security by Default:</strong> OpenShift restricts containers from running as <code>root</code> right out of the box using Security Context Constraints (SCC).</li><li><strong>Projects vs Namespaces:</strong> OpenShift extends K8s namespaces into &quot;Projects&quot; which have built-in annotations and user access controls.</li><li><strong>Routes vs Ingress:</strong> While K8s uses Ingress, OpenShift uses &quot;Routes&quot; (backed by HAProxy) to expose services to the outside world.</li><li><strong>Integrated Registry &amp; Builds:</strong> OpenShift has an internal container registry and native resources for building images from source code (BuildConfigs and Source-to-Image).</li><li><strong>Web Console:</strong> OpenShift ships with a highly advanced, dual-perspective (Developer vs Administrator) web console out of the box.</li></ol><h2 id="the-oc-cli-vs-kubectl" tabindex="-1">The <code>oc</code> CLI vs <code>kubectl</code> <a class="header-anchor" href="#the-oc-cli-vs-kubectl" aria-label="Permalink to &quot;The \`oc\` CLI vs \`kubectl\`&quot;">​</a></h2><p>The primary command-line tool for OpenShift is <code>oc</code>.</p><p>Because OpenShift is fully compliant Kubernetes, <strong><code>oc</code> is completely backwards compatible with <code>kubectl</code></strong>. Every <code>kubectl</code> command works exactly the same in <code>oc</code>. However, <code>oc</code> adds commands specifically for OpenShift features.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># These commands do exactly the same thing</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pods</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">oc</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pods</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># This command ONLY works in OpenShift (creates a new Project)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">oc</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> new-project</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-app</span></span></code></pre></div><h3 id="authentication-and-contexts" tabindex="-1">Authentication and Contexts <a class="header-anchor" href="#authentication-and-contexts" aria-label="Permalink to &quot;Authentication and Contexts&quot;">​</a></h3><p>In vanilla K8s, you manually manage your <code>~/.kube/config</code> file. In OpenShift, you typically log in dynamically via an API endpoint.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Log into the cluster (prompts for username/password or a token)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">oc</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> login</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://api.mycluster.example.com:6443</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Check who you are currently logged in as</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">oc</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> whoami</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Check your current session context</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">oc</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> current-context</span></span></code></pre></div><h3 id="the-oc-new-app-magic" tabindex="-1">The <code>oc new-app</code> Magic <a class="header-anchor" href="#the-oc-new-app-magic" aria-label="Permalink to &quot;The \`oc new-app\` Magic&quot;">​</a></h3><p>OpenShift is designed to make deploying apps effortless for developers. The <code>oc new-app</code> command can take a Git repository, automatically detect the language (Node, Python, Java), build the container image via S2I (Source-to-Image), deploy it, and spin up the pods—all in one command.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Deploy an application directly from source code</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">oc</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> new-app</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/sclorg/nodejs-ex.git</span></span></code></pre></div>`,18)])])}const k=s(t,[["render",o]]);export{u as __pageData,k as default};
